// Scientific input generated by hf_fdtd/examples/field_cut_2d.py.
use anyhow::Result;
use hdf5::File;
use rustplotlib::*;
fn rd(h:&File,k:&str)->Result<Vec<f64>>{Ok(h.dataset(k)?.read_raw::<f64>()?)}
fn main()->Result<()>{
 let h=File::open("output/hf_fdtd/field_cut_2d.h5")?;
 for name in ["overview","resonance"]{
  let mut f=Figure::new(IntendedUse::ArticleWide);let p=f.grid(1,1)?[0];
  f.width_mm=195.;f.height_mm=191.;f.panels[p].rect=Rect::new(29.,10.,148.,136.);
  let x=rd(&h,&format!("{name}/horizontal_edges_m"))?;
  let y=rd(&h,&format!("{name}/{}",if name=="overview"{"height_edges_km"}else{"height_relative_edges_m"}))?;
  let values=rd(&h,&format!("{name}/instantaneous_magnitude_over_incident"))?;
  f.panels[p].axes=Some(Axes::new([x[0],*x.last().unwrap()],[y[0],*y.last().unwrap()],"Horizontal distance (m)",if name=="overview"{"Altitude above radar (km)"}else{"Height relative to resonance (m)"}));
  let sc=f.scale(Scale::new([0.01,200.],Normalization::Log,ColorMap::ember())?);
  f.panels[p].push(Layer::Pcolormesh(Field::new(x,y,values,sc)?));
  let mut cb=Colorbar::new(Rect::new(29.,168.,148.,3.),sc,r"Instantaneous field magnitude $|\mathbf{E}|/|E_{\rm inc}|$",vec![0.01,0.1,1.,10.,100.,200.]);
  cb.horizontal=true;f.colorbars.push(cb);f.layout_colorbars()?;
  for ext in ["png","pdf"]{f.save(format!("figures/hf_field_cut_{name}.{ext}"))?;}
 }
 for name in ["overview","resonance"] {
  for comp in ["x","y","z"] {
   let mut f=Figure::new(IntendedUse::ArticleWide);let p=f.grid(1,1)?[0];
   f.width_mm=195.;f.height_mm=191.;f.panels[p].rect=Rect::new(29.,10.,148.,136.);
   let x=rd(&h,&format!("{name}/horizontal_edges_m"))?;
   let y=rd(&h,&format!("{name}/{}",if name=="overview"{"height_edges_km"}else{"height_relative_edges_m"}))?;
   let values=rd(&h,&format!("{name}/instantaneous_E{comp}_over_incident"))?;
   let peak=values.iter().fold(0f64,|a,&v|a.max(v.abs()));
   let (lim,ticks,norm)=if comp=="z" {(200.,vec![-200.,-10.,-1.,0.,1.,10.,200.],Normalization::Asinh{width:0.5})}
    else {let lim=peak.ceil().max(1.);(lim,vec![-lim,-lim/2.,0.,lim/2.,lim],Normalization::Linear)};
   f.panels[p].axes=Some(Axes::new([x[0],*x.last().unwrap()],[y[0],*y.last().unwrap()],"Horizontal distance (m)",if name=="overview"{"Altitude above radar (km)"}else{"Height relative to resonance (m)"}));
   let sc=f.scale(Scale::new([-lim,lim],norm,ColorMap::diverging())?);
   f.panels[p].push(Layer::Pcolormesh(Field::new(x,y,values,sc)?));
   let label=format!("Instantaneous electric field $E_{comp}/|E_{{\\rm inc}}|$");
   let mut cb=Colorbar::new(Rect::new(29.,168.,148.,3.),sc,label,ticks);cb.horizontal=true;
   f.colorbars.push(cb);f.layout_colorbars()?;
   for ext in ["png","pdf"] {f.save(format!("figures/hf_field_cut_E{comp}_{name}.{ext}"))?;}
  }
 }
 Ok(())
}
